/* Browser-local UI. All AWS-shaped records and operational signals are synthetic. */
(() => {
  'use strict';
  const M = window.RH_MODEL;
  const STORE = 'northstar-resilience-workspace-v3';
  const LEGACY_STORE = 'northstar-resilience-workspace-v2';
  const LEGACY_NOTICE = STORE + '-legacy-notice-shown';
  const fresh = () => M.createState();
  let state = fresh();
  let persistenceAvailable = true;
  let legacyCacheNotice = false;
  try {
    const saved = JSON.parse(localStorage.getItem(STORE) || 'null');
    if (saved && saved.schemaVersion === state.schemaVersion && ['services','systems','journeys','findings','assessments','policies','dependencies','topologies','events'].every(k => Array.isArray(saved[k]))) state = saved;
    else if (localStorage.getItem(LEGACY_STORE) && !localStorage.getItem(LEGACY_NOTICE)) {
      legacyCacheNotice = true;
      localStorage.setItem(LEGACY_NOTICE, 'true');
    }
  } catch (_) { persistenceAvailable = false; }
  const views = ['overview','systems','services','findings','dependencies','events','model'];
  const ui = {view: views.includes(location.hash.slice(1)) ? location.hash.slice(1) : 'overview', systemId:'all',journeyId:'all',query:'',severity:'all',findingStatus:'OPEN',criticality:'all',eventChannel:'all',diagram:0,serviceId:null,tab:'overview',inspector:null,nodeId:null,edgeType:'all',menu:false};
  const $ = id => document.getElementById(id);
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
    systems:'M3 5h7v6H3z M14 13h7v6h-7z M6.5 11v6h7.5 M10 8h7.5v5',
    service:'M5 3h14v6H5z M5 15h14v6H5z M8 6h.01 M8 18h.01 M12 9v6',
    shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z M8 12l3 3 5-6',
    alert:'m12 3 10 17H2z M12 9v5 M12 17h.01',
    pulse:'M2 12h4l3-8 5 16 3-8h5',
    network:'M8 5a3 3 0 1 0-6 0 3 3 0 0 0 6 0 M22 5a3 3 0 1 0-6 0 3 3 0 0 0 6 0 M15 19a3 3 0 1 0-6 0 3 3 0 0 0 6 0 M8 5h8 M6 8l4 8 M18 8l-4 8',
    clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',
    book:'M12 5C8 2 4 3 2 4v15c3-2 7-1 10 1 3-2 7-3 10-1V4c-2-1-6-2-10 1z M12 5v15',
    arrow:'M5 12h14 M13 6l6 6-6 6',
    chevron:'m9 5 7 7-7 7',
    down:'m6 9 6 6 6-6',
    search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0 M15 15l6 6',
    refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 3 M18 18A8 8 0 0 1 5 15',
    play:'m8 4 12 8-12 8z',
    download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',
    external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',
    close:'m5 5 14 14 M19 5 5 19',
    check:'m5 12 4 4L19 6',
    info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',
    layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',
    menu:'M3 6h18 M3 12h18 M3 18h18',
    globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',
    file:'M14 2H5v20h14V7z M14 2v5h5 M8 12h8 M8 16h6',
    bolt:'m13 2-9 12h7l-1 8 10-13h-8z',
    code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',
    target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 12h.01',
    user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',
    star:'M12 1v22 M1 12h22 M4 4l16 16 M20 4 4 20'
  };
  const icon = (name,cls='') => `<svg class="icon ${e(cls)}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.service}"/></svg>`;
  const human = value => ({ACHIEVABLE:'Achievable',NOT_ACHIEVABLE:'At risk',UNKNOWN:'Unknown',HEALTHY:'Healthy',DEGRADED:'Degraded',UNAVAILABLE:'Unavailable',IN_PROGRESS:'In progress',NOT_STARTED:'Not started',PENDING:'Queued',SUCCESS:'Completed',FAILED:'Failed',OPEN:'Open',RESOLVED:'Resolved',IRRELEVANT:'Irrelevant',INITIALIZING:'Initializing',ENABLED:'Enabled',DISABLED:'Disabled',SUCCEEDED:'Succeeded',RUNNING:'Running',COMPLETED_WITH_FAILURES:'Partial failure',HIGH:'High',MEDIUM:'Medium',LOW:'Low',COMPLETE:'Complete',PARTIAL:'Partial',SELF:'Same account',CROSS_ACCOUNT:'Cross account',HARD:'Hard',SOFT:'Soft',REVIEW:'Needs review',ALLOWED:'Allowed',DENIED:'Denied',LOCAL:'Local action',ENTITY_TIMELINE:'Entity timeline',EVENTBRIDGE:'EventBridge',TELEMETRY:'Telemetry',REFRESHED:'Refreshed',LOCAL_ONLY:'Local action',IGNORED_DUPLICATE:'Duplicate ignored',OLDER_EVIDENCE:'Older evidence'}[value] || String(value || 'Unknown').replace(/_/g,' ').toLowerCase().replace(/^./,s=>s.toUpperCase()));
  const tone = value => ['ACHIEVABLE','HEALTHY','SUCCESS','ENABLED','SUCCEEDED','COMPLETE','LOW','ALLOWED'].includes(value)?'good':['WARNING','NOT_ACHIEVABLE','DEGRADED','MEDIUM','INITIALIZING','PARTIAL','COMPLETED_WITH_FAILURES','REVIEW'].includes(value)?'warn':['ERROR','UNAVAILABLE','HIGH','FAILED','DENIED'].includes(value)?'bad':['IN_PROGRESS','PENDING','RUNNING'].includes(value)?'info':'neutral';
  const badge = (value,label) => `<span class="badge ${tone(value)}"><span class="dot"></span>${e(label ?? human(value))}</span>`;
  const getService = id => state.services.find(s=>s.id===id);
  const serviceName = id => getService(id)?.name || id || 'Workspace';
  const utcTime = (value,withDate=false) => {if(!value)return 'Not reported';const d=new Date(value);if(Number.isNaN(+d))return 'Unknown';return new Intl.DateTimeFormat('en-GB',{...(withDate?{day:'2-digit',month:'short'}:{}),hour:'2-digit',minute:'2-digit',timeZone:'UTC',hour12:false}).format(d)+' UTC';};
  const ago = value => {if(!value)return 'Not observed';const m=Math.max(0,Math.round((new Date(state.now)-new Date(value))/60000));return m<1?'Just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;};
  const number = v => new Intl.NumberFormat('en-US').format(v ?? 0);
  const scopedServices = (query=true) => M.servicesInScope(state,{systemId:ui.systemId,journeyId:ui.journeyId,query:query?ui.query:''});
  const scopedIds = () => new Set(scopedServices(false).map(s=>s.id));
  const health = s => M.serviceHealth(state,s);
  const posture = s => M.servicePosture(state,s);
  const findings = s => M.serviceFindings(state,s.id);
  const openFindings = s => findings(s).filter(f=>f.status==='OPEN');
  const coverage = s => M.assessmentCoverage(state,s);
  const coverageLabels = {CURRENT:'Current evidence',STALE:'Stale evidence',PARTIAL:'Partial evidence',UNASSESSED:'Not assessed',INACCESSIBLE:'Access gap'};
  const attentionLabels = {HEALTH_EVIDENCE_EXPIRED:'Health signal expired',HEALTH_UNKNOWN:'Health unknown',RUNTIME_HEALTH_DEGRADED:'Runtime degraded',RUNTIME_HEALTH_UNAVAILABLE:'Runtime unavailable',UNMET_OBJECTIVES:'Unmet objectives',POSTURE_UNKNOWN:'Posture unknown',POSTURE_STALE:'Posture aging',OPEN_FINDINGS:'Observed open findings',FINDING_COLLECTION_INCOMPLETE:'Finding coverage gap',ASSESSMENT_FAILED:'Assessment failed',ASSESSMENT_EVIDENCE_GAP:'Assessment evidence gap',RESOURCE_DISCOVERY_GAP:'Resource coverage gap',DEPENDENCY_DISCOVERY_GAP:'Dependency coverage gap',POLICY_CONTEXT_REFRESH_REQUIRED:'Assessment context changed',LOCAL_REASSESSMENT_REQUIRED:'Independent reassessment required',NATIVE_REASSESSMENT_REQUIRED:'Provider requests reassessment'};
  const recommendationCount = f => Array.isArray(f.recommendations)?`${f.recommendations.length} recommendation groups`:f.recommendations===null?'Recommendation detail unavailable':'Recommendation detail not fetched';
  function findingCollection(s) {
    return M.findingCoverage(state,s);
  }
  function serviceEvidence(s) {
    const c=coverage(s),reasons=M.attentionReasons(state,s);
    return `<section class="panel evidence-summary"><div class="panel-head"><h2>Evidence & attention</h2>${badge(c.current?'SUCCESS':c.status,coverageLabels[c.status])}</div><div class="panel-body"><p>${e(c.reason)}${c.lastKnown?` Last known assessment evidence: ${ago(c.observedAt)}.`:''}</p><p class="tiny muted">Current coverage uses a local 24-hour review cadence. Retained history is reported separately. A failed newer run does not erase earlier evidence.</p>${reasons.length?`<ul class="attention-reasons">${reasons.map(reason=>`<li><b>${e(attentionLabels[reason.code]||human(reason.code))}.</b> ${e(reason.message)}${reason.observedAt?` <span class="tiny muted">${ago(reason.observedAt)}</span>`:''}</li>`).join('')}</ul>`:'<p class="tiny muted">No current attention reasons in this scope.</p>'}</div></section>`;
  }
  const modelDescriptions = [
    ['Business structure','01-business-structure','Services can belong to several systems and journeys. Journey membership is a set of service associations; it does not imply a request sequence or critical path.'],
    ['Policy context','02-policy-context','Direct and inherited assignments are distinct from account ownership. An observed effective target is retained with context; it does not claim a provider policy revision used by an assessment.'],
    ['Assessments & findings','03-assessments-findings','Assessments and findings are separate children of a service. Finding observations have explicit identities, separate summary/detail coverage, and snapshot-owned recommendation groups.'],
    ['Dependencies & topology','04-dependencies-topology','DNS dependencies and topology edges have separate evidence. Locally captured graph nodes and edge endpoints share a snapshot scope; a complete collection is not an atomic AWS snapshot.'],
    ['Events & observations','05-events-observations','Events trigger targeted refreshes. Runtime health, service posture and derived business attention retain separate evidence, timestamps and coverage. Current projections are replaceable.']
  ];
  function save() { try {localStorage.setItem(STORE,JSON.stringify(state));}catch(_){persistenceAvailable=false;toast('Browser storage is unavailable. Changes remain in this tab; export a snapshot to retain them.');} }
  let toastTimer;
  function toast(message) { $('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),5000); }
  function mutate(result) { if(!result?.ok){toast(result?.message || 'The action could not be completed.');return;}save();render();if(ui.serviceId)renderService();toast(result.message || 'Demo updated.'); }
  function navigate(view) {ui.view=view;ui.menu=false;ui.query='';history.replaceState(null,'','#'+view);render();$('main').focus({preventScroll:true});}
  function layout() {
    const nav=[['overview','grid','Overview'],['systems','systems','Systems & journeys'],['services','service','Services'],['findings','alert','Findings'],['dependencies','network','Dependencies'],['events','pulse','Event stream'],['model','book','Data model']];
    return `<div class="app-shell ${ui.menu?'menu-open':''}"><button class="nav-backdrop" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#overview" data-action="navigate" data-view="overview"><span class="brand-mark">${icon('star')}</span><span>northstar<small>Resilience workspace</small></span></a><div class="workspace-selector"><span class="initials">NC</span><span>Northstar Commerce<br><small class="tiny" style="color:#91a9b4">Organization workspace</small></span></div><div class="nav-label">OPERATE</div><nav class="nav">${nav.map(([id,ic,label])=>`<button data-action="navigate" data-view="${id}" class="${ui.view===id?'active':''}" ${ui.view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='findings'?`<span class="nav-count">${state.findings.filter(f=>f.status==='OPEN').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-note"><b>A model you can explore</b><br>Synthetic operations, real API boundaries. Changes stay in this browser.</div><div class="sidebar-user"><span class="avatar">AL</span><span>Alex Laurent<small>Platform operations · Demo</small></span></div></div></aside><div class="main-shell"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb"><span class="organization-crumb">Northstar Commerce</span><span class="slash">/</span><span>Resilience Hub</span></div></div><div class="topbar-right"><span class="environment"><span class="dot env-dot"></span>Production</span><span class="demo-pill">MOCK DATA</span><span class="topbar-divider"></span><button class="icon-button" data-action="reset-confirm" title="Reset demo data" aria-label="Reset demo data">${icon('refresh')}</button><span class="avatar">AL</span></div></header><main id="main" tabindex="-1" class="focus-heading">${legacyCacheNotice?`<div class="notice amber" role="status">${icon('info')}<p>This reviewed demo uses a fresh fixture because earlier assessment conclusions were invalid. The earlier saved session is retained separately and is not included in exports or reset.</p><button class="button small" data-action="dismiss-cache-notice" aria-label="Dismiss reviewed demo notice">Dismiss</button></div>`:''}${page()}</main></div></div>`;
  }
  const pageTitles={overview:['Operations overview','Know what is happening. Understand what is at risk.'],systems:['Systems & user journeys','See the business context behind each service and its resilience targets.'],services:['Service inventory','Assess execution, resilience posture, live health and discovery independently.'],findings:['Failure mode findings','Prioritize failure modes and review suggested changes across your services.'],dependencies:['Discovered dependencies','Understand external reliance, criticality and the limits of discovery.'],events:['Event stream','Follow operational signals, refreshes and operator actions as they arrive.'],model:['The model behind the workspace','A reviewed, traceable foundation for an event-driven operator experience.']};
  function header() {const [title,description]=pageTitles[ui.view];return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="page-head-actions">${ui.view==='model'?`<a class="button" href="report.md" target="_blank" rel="noopener">${icon('file')}Reviewed report</a>`:`<button class="button" data-action="export">${icon('download')}Export snapshot</button>`}<button class="button primary" data-action="scenarios">${icon('play')}Simulate event</button></div></div>`;}
  function scopeFilters() {return `<div class="filters"><label class="sr-only" for="system-filter">System</label><select id="system-filter" class="filter-select" aria-label="Filter by system"><option value="all">All systems</option>${state.systems.map(s=>`<option value="${e(s.id)}" ${s.id===ui.systemId?'selected':''}>${e(s.name)}</option>`).join('')}</select><select id="journey-filter" class="filter-select" aria-label="Filter by user journey"><option value="all">All user journeys</option>${state.journeys.filter(j=>ui.systemId==='all'||j.systemId===ui.systemId).map(j=>`<option value="${e(j.id)}" ${j.id===ui.journeyId?'selected':''}>${e(j.name)}</option>`).join('')}</select><span class="scope-note">${icon('layers')}Shared services counted once</span><div class="search-box">${icon('search')}<input id="search" type="search" placeholder="${ui.view==='findings'?'Search findings…':ui.view==='dependencies'?'Search dependencies…':'Search services…'}" value="${e(ui.query)}" aria-label="Search ${ui.view==='findings'?'findings':ui.view==='dependencies'?'dependencies':'services'}"></div></div>`;}
  function page() {let content='';if(ui.view==='overview')content=overview();if(ui.view==='systems')content=systemsPage();if(ui.view==='services')content=serviceTable(scopedServices(),true);if(ui.view==='findings')content=findingsPage();if(ui.view==='dependencies')content=dependenciesPage();if(ui.view==='events')content=eventsPage();if(ui.view==='model')content=modelPage();return header()+(!['systems','events','model'].includes(ui.view)?scopeFilters():'')+content+`<footer class="bottom-line"><span class="row">${icon('clock')}<span>Demo clock · <span class="demo-clock">${utcTime(state.now,true)}</span> · advances when you simulate an event</span></span><span>${persistenceAvailable?'Changes saved in this browser':'Browser persistence unavailable'} · <button class="link tiny" data-action="navigate" data-view="model">Model & source notes</button></span></footer>`;}
  function summaryCards() {
    const services=scopedServices(),m=M.metrics(state,{systemId:ui.systemId,journeyId:ui.journeyId,query:ui.query});
    const healthy=m.healthy,unknown=m.unknownHealth,degraded=m.degraded+m.unavailable;
    const achievable=services.filter(s=>posture(s).state==='ACHIEVABLE').length,risk=m.achievabilityAttention;
    const fs=services.flatMap(openFindings),high=m.highFindings,active=m.activeAssessments;
    const collected=services.filter(s=>findingCollection(s).status==='COMPLETE').length;
    const track=states=>`<div class="mini-track" aria-hidden="true">${states.map(v=>`<span class="${v}"></span>`).join('')}</div>`;
    return `<div class="stats-grid"><article class="stat-card"><div class="stat-top">Runtime health<span class="stat-icon">${icon('pulse')}</span></div><div class="stat-value">${healthy}<small>/ ${services.length} healthy</small></div><div class="stat-foot">${degraded?`${degraded} degraded or unavailable`:'No active degradation'}${unknown?` · ${unknown} unknown`:''}</div>${track(services.map(s=>({HEALTHY:'good',DEGRADED:'warn',UNAVAILABLE:'bad',UNKNOWN:'unknown'}[health(s).state])))}</article><article class="stat-card"><div class="stat-top">Resilience posture<span class="stat-icon amber">${icon('shield')}</span></div><div class="stat-value">${risk}<small>services at risk</small></div><div class="stat-foot">${achievable} last known achievable · ${services.length-m.lastKnownAssessed} awaiting evidence</div>${track(services.map(s=>posture(s).state==='ACHIEVABLE'?(coverage(s).current?'good':'warn'):posture(s).state==='NOT_ACHIEVABLE'?'warn':'unknown'))}</article><article class="stat-card"><div class="stat-top">Observed open findings<span class="stat-icon amber">${icon('alert')}</span></div><div class="stat-value">${fs.length}<small>observed failure modes</small></div><div class="stat-foot">${high?`<span class="text-bad">${high} high severity</span>`:'No observed high-severity findings'} · ${collected}/${services.length} services fully covered</div>${track(fs.map(f=>f.severity==='HIGH'?'bad':f.severity==='MEDIUM'?'warn':'good'))}</article><article class="stat-card"><div class="stat-top">Current assessment coverage<span class="stat-icon blue">${icon('target')}</span></div><div class="stat-value">${m.currentAssessmentCoverage??'—'}<small>${services.length?'% of services':'No services in scope'}</small></div><div class="stat-foot">${m.currentAssessed} current · ${m.lastKnownAssessed} last known · ${active} active</div><div class="stat-foot">24-hour cadence · incomplete evidence excluded</div>${track(services.map(s=>coverage(s).current?'good':coverage(s).lastKnown?'warn':'unknown'))}</article></div>`;
  }
  function overview() {return summaryCards()+`<div class="content-grid"><div class="stack">${serviceTable(scopedServices(),false)}<div class="notice neutral">${icon('info')}<p><b>Health and posture answer different questions.</b> Health reflects recent telemetry. Posture reflects resilience objectives from the last available assessment. A healthy service can still be at risk.</p></div></div><div class="stack aside-column">${priorities()}${businessPanel()}${activityPanel()}</div></div>`;}
  function serviceTable(services,full) {return `<section class="panel"><div class="panel-head"><div><h2>${full?'Services':'Service watchlist'}<span class="count-label">${services.length}</span></h2><p>${full?'Select a service to inspect its evidence and relationships.':'Live health alongside the last available resilience posture.'}</p></div>${!full?`<button class="link" data-action="navigate" data-view="services">View all ${icon('arrow')}</button>`:''}</div>${services.length?`<div class="table-wrap"><table class="service-table"><thead><tr><th>Service</th><th>Health</th><th>Posture</th><th>Findings</th><th class="optional-col">Last assessed</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${services.map(s=>{const h=health(s),p=posture(s),c=coverage(s),fs=openFindings(s),reasons=M.attentionReasons(state,s),collection=findingCollection(s);return `<tr><td><div class="service-cell"><span class="service-glyph">${icon(s.id==='identity'?'shield':s.id==='edge'?'globe':s.id==='payments'?'layers':'service')}</span><span><button class="service-name" data-action="service" data-id="${e(s.id)}">${e(s.name)}</button><small class="cell-sub">${e(s.owner)}${(s.associations?.length||0)>1?` · Shared across ${s.associations.length} systems`:''}</small><small class="cell-sub">${reasons.length?`${reasons.length} attention reason${reasons.length===1?'':'s'}`:'No current attention reasons'}</small></span></div></td><td>${badge(h.state)}${h.stale?'<span class="cell-sub">Signal expired</span>':''}</td><td>${badge(p.state)}${!c.current?`<span class="cell-sub text-warn">${e(coverageLabels[c.status])}</span>`:''}${s.assessmentStatus==='FAILED'?'<span class="cell-sub text-bad">Latest run failed</span>':['IN_PROGRESS','PENDING'].includes(s.assessmentStatus)?`<span class="cell-sub text-good">${human(s.assessmentStatus)}</span>`:''}</td><td><span class="finding-count ${fs.some(f=>f.severity==='HIGH')?'high':''}">${collection.latestCapture||collection.observedCount?collection.observedOpenCount:'—'}</span><span class="cell-sub">${collection.latestCapture||collection.observedCount?`${fs.filter(f=>f.severity==='HIGH').length} high · observed open`: 'Not collected'}${collection.status!=='COMPLETE'&&collection.latestCapture?` · ${e(human(collection.status))} coverage`:''}</span></td><td class="optional-col"><span class="muted">${ago(p.observedAt)}</span>${p.stale?'<span class="cell-sub">Posture aging</span>':''}</td><td><button class="icon-button" data-action="service" data-id="${e(s.id)}" aria-label="Inspect ${e(s.name)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching services','Try another system, user journey or search.') }<div class="table-footer">${icon('layers')}Service and finding counts are deduplicated across associations.</div></section>`;}
  function priorities() {
    const rank={ERROR:3,WARNING:2,INFO:1};
    const entries=scopedServices().map(service=>({service,reasons:M.attentionReasons(state,service).sort((a,b)=>rank[b.severity]-rank[a.severity])})).filter(entry=>entry.reasons.length).sort((a,b)=>rank[b.reasons[0].severity]-rank[a.reasons[0].severity]||b.reasons.length-a.reasons.length);
    const shown=entries.slice(0,4);
    return `<section class="panel"><div class="panel-head"><h2>Needs your attention <span class="count-label">${entries.length}</span></h2>${icon('bolt')}</div><div class="panel-body">${shown.map(({service,reasons})=>`<article class="priority ${reasons[0].severity==='INFO'?'neutral':''}"><div class="priority-header"><h3>${e(service.name)}</h3>${badge(reasons[0].severity,attentionLabels[reasons[0].code]||human(reasons[0].code))}</div><p>${e(reasons[0].message)}</p><p class="tiny muted">${reasons.length} attention reason${reasons.length===1?'':'s'}${reasons.length>1?' · '+reasons.slice(1).map(reason=>e(attentionLabels[reason.code]||human(reason.code))).join(', '):''}</p><button class="link" data-action="service" data-id="${e(service.id)}">Inspect evidence ${icon('arrow')}</button></article>`).join('')}${!entries.length?'<p class="muted tiny">No current service attention signals in this scope.</p>':''}${entries.length>shown.length?`<p class="tiny muted">Showing ${shown.length} of ${entries.length} distinct services needing attention. Open findings and coverage gaps are included.</p><button class="link tiny" data-action="navigate" data-view="services">Review all scoped services ${icon('arrow')}</button>`:''}</div></section>`;
  }
  function businessPanel() {return `<section class="panel"><div class="panel-head"><h2>Business context</h2><button class="link" data-action="navigate" data-view="systems">Explore</button></div><div class="panel-body">${state.systems.map(s=>{const members=M.servicesInScope(state,{systemId:s.id,journeyId:'all',query:''});const attention=members.filter(x=>M.needsAttention(state,x)).length;return `<div class="business-row"><span class="business-avatar">${e(s.name.split(' ').map(t=>t[0]).slice(0,2).join(''))}</span><div class="grow"><h3><button class="service-name" data-action="scope-system" data-id="${e(s.id)}">${e(s.name)}</button></h3><p>${members.length} services · ${state.journeys.filter(j=>j.systemId===s.id).length} journeys</p></div><span class="business-count ${attention?'':'text-good'}">${attention?`${attention} attention`:'Clear'}</span></div>`;}).join('')}</div></section>`;}
  function eventMarker(ev) {return icon(ev.channel==='TELEMETRY'?'pulse':/dependency/i.test(ev.type||'')?'network':['HIGH','ERROR','WARNING'].includes(ev.severity)?'alert':ev.channel==='LOCAL'?'user':/completed|resolved/i.test(ev.type||'')?'check':'info');}
  function activityPanel() {return `<section class="panel activity-panel"><div class="panel-head"><h2>Latest activity</h2><button class="link" data-action="navigate" data-view="events">All events</button></div><div class="panel-body">${[...state.events].sort((a,b)=>new Date(b.receivedAt)-new Date(a.receivedAt)).slice(0,3).map(ev=>`<div class="stream-entry"><span class="stream-marker ${tone(ev.severity)}">${eventMarker(ev)}</span><div class="grow"><h3><button class="service-name" data-action="event" data-id="${e(ev.id)}">${e(ev.title)}</button></h3><p>${e(serviceName(ev.serviceId))} · ${ago(ev.occurredAt)}</p></div></div>`).join('')}</div></section>`;}
  function systemsPage() {return `<div class="notice">${icon('layers')}<p>Services can be shared across systems and journeys. Attention counts identify member services to investigate; they do not certify journey compliance with a separate, potentially looser policy.</p></div><div class="system-grid">${state.systems.map(sys=>{const services=M.servicesInScope(state,{systemId:sys.id,journeyId:'all',query:''}),attention=services.filter(s=>M.needsAttention(state,s)).length;return `<article class="system-card"><div class="row between"><span class="business-avatar">${icon('systems')}</span><span class="badge outline">System</span></div><h2>${e(sys.name)}</h2><p>${e(sys.description)}</p><div class="system-facts"><div><b>${services.length}</b><small>Distinct services</small></div><div><b class="text-warn">${attention}</b><small>Need attention</small></div><div><b>${services.flatMap(openFindings).length}</b><small>Open findings</small></div></div><button class="link tiny" data-action="scope-system" data-id="${e(sys.id)}">View service status →</button><div class="journey-list">${state.journeys.filter(j=>j.systemId===sys.id).map(j=>{const members=M.servicesInScope(state,{systemId:sys.id,journeyId:j.id,query:''}),policy=state.policies.find(p=>p.id===j.policyId);return `<section class="journey-card"><div class="eyebrow">User journey</div><h3 style="margin-top:7px">${e(j.name)}</h3><p>${e(j.description)}</p><div class="chips">${members.map(s=>`<button class="chip" data-action="service" data-id="${s.id}">${e(s.name)}</button>`).join('')}</div><p style="margin:12px 0 0">${icon('shield')} ${e(policy?.name||'No assigned policy')}</p><button class="link tiny" data-action="scope-journey" data-id="${e(j.id)}" style="margin-top:10px">Inspect journey services →</button></section>`;}).join('')}</div></article>`;}).join('')}</div>`;}
  function filteredFindings() {const ids=scopedIds();return state.findings.filter(f=>ids.has(f.serviceId)&&(ui.findingStatus==='all'||f.status===ui.findingStatus)&&(ui.severity==='all'||f.severity===ui.severity)&&`${f.name} ${f.description} ${serviceName(f.serviceId)}`.toLowerCase().includes(ui.query.toLowerCase())).sort((a,b)=>({HIGH:0,MEDIUM:1,LOW:2}[a.severity]-{HIGH:0,MEDIUM:1,LOW:2}[b.severity]));}
  function findingsPage() {const list=filteredFindings();return `<section class="panel"><div class="panel-head"><div><h2>Findings <span class="count-label">${list.length}</span></h2><p>Service-scoped failure modes with captured recommendation details.</p></div><span class="badge outline">${list.filter(f=>f.severity==='HIGH').length} high severity</span></div><div class="toolbar"><label>Status <select id="finding-status">${['OPEN','RESOLVED','IRRELEVANT','all'].map(v=>`<option value="${v}" ${ui.findingStatus===v?'selected':''}>${v==='all'?'All statuses':human(v)}</option>`).join('')}</select></label><label>Severity <select id="severity-filter">${['all','HIGH','MEDIUM','LOW'].map(v=>`<option value="${v}" ${ui.severity===v?'selected':''}>${v==='all'?'All severities':human(v)}</option>`).join('')}</select></label><span class="grow"></span><small class="muted tiny">Triage does not validate remediation</small></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Failure mode</th><th>Service</th><th>Severity</th><th>Status</th><th>Updated</th></tr></thead><tbody>${list.map(f=>`<tr><td><button class="service-name" data-action="finding" data-id="${e(f.id)}">${e(f.name)}</button><span class="cell-sub">${e(human(f.failureCategory))}</span></td><td><button class="link tiny" data-action="service" data-id="${e(f.serviceId)}">${e(serviceName(f.serviceId))}</button></td><td>${badge(f.severity)}</td><td>${badge(f.status)}${f.verification==='UNVERIFIED'&&f.status==='RESOLVED'?'<span class="cell-sub">Verification pending</span>':''}</td><td class="muted nowrap">${ago(f.updatedAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('No findings in this view','Try another status, severity or search.') }<div class="table-footer">${icon('info')}Finding observations are correlated with captures; no native assessment ownership is inferred.</div></section>`;}
  function dependenciesPage() {const ids=scopedIds(),services=scopedServices(false),list=state.dependencies.filter(d=>ids.has(d.serviceId)&&(ui.criticality==='all'||d.criticality===ui.criticality)&&`${d.name} ${d.dnsName} ${serviceName(d.serviceId)}`.toLowerCase().includes(ui.query.toLowerCase()));const enabled=services.filter(s=>s.dependencyDiscovery?.status==='ENABLED').length,eligible=services.filter(s=>(s.dependencyDiscovery?.eligibleResourceCount||0)>0).length;return `<div class="coverage-grid"><article class="coverage-card"><span class="eyebrow">DNS dependencies</span><strong>${list.length}</strong><p>Observed consumer relationships</p></article><article class="coverage-card"><span class="eyebrow">Discovery enabled</span><strong>${enabled}<small class="muted"> / ${services.length}</small></strong><p>Configuration is separate from coverage</p></article><article class="coverage-card"><span class="eyebrow">Eligible resources</span><strong>${eligible}<small class="muted"> services</small></strong><p>Positive eligibility does not prove full coverage</p></article></div><div class="notice neutral">${icon('info')}<p>DNS observations show discovered reliance, not request success or dependency health. “Allowed” is a Northstar governance label. Empty results may reflect disabled discovery or a coverage gap.</p></div><section class="panel"><div class="panel-head"><h2>Dependency inventory</h2><label class="row tiny muted">Criticality <select id="criticality-filter" class="filter-select">${['all','HARD','SOFT','UNKNOWN'].map(v=>`<option value="${v}" ${ui.criticality===v?'selected':''}>${v==='all'?'All criticalities':human(v)}</option>`).join('')}</select></label></div>${dependencyTable(list,true)}</section>`;}
  function dependencyTable(list,withService=false) {if(!list.length)return empty('No dependencies in this view','Review discovery configuration and eligibility before interpreting an empty list.');return `<div class="table-wrap"><table><thead><tr><th>Dependency</th>${withService?'<th>Consumer</th>':''}<th>Location</th><th>Criticality</th><th>Governance</th><th>Last detected</th></tr></thead><tbody>${list.map(d=>`<tr><td><button class="dependency-name" data-action="dependency" data-id="${e(d.id)}">${e(d.name)}</button><span class="cell-sub mono">${e(d.dnsName)}</span></td>${withService?`<td><button class="link tiny" data-action="service" data-id="${e(d.serviceId)}">${e(serviceName(d.serviceId))}</button></td>`:''}<td class="muted">${e(human(d.location))}</td><td><span class="criticality ${d.criticality==='HARD'?'text-warn':'text-neutral'}">${e(d.criticality)}</span></td><td>${badge(d.governance?.allowedStatus || 'UNKNOWN')}<span class="cell-sub">Local policy</span></td><td class="muted nowrap">${ago(d.lastDetectedTime)}</td></tr>`).join('')}</tbody></table></div>`;}
  function eventsPage() {const list=[...state.events].filter(ev=>ui.eventChannel==='all'||ev.channel===ui.eventChannel).sort((a,b)=>new Date(b.receivedAt)-new Date(a.receivedAt));return `<div class="notice neutral">${icon('refresh')}<p>Events trigger an authoritative refresh. Best-effort delivery is backed by reconciliation; older evidence cannot replace a newer observation. The demo runs locally with a controlled clock.</p></div><section class="panel"><div class="panel-head"><div><h2>Activity timeline <span class="count-label">${list.length}</span></h2><p>Ordered by receipt time; source occurrence time is retained in each event.</p></div><label class="row tiny muted">Source <select id="event-channel" class="filter-select">${['all','EVENTBRIDGE','ENTITY_TIMELINE','TELEMETRY','LOCAL'].map(v=>`<option value="${v}" ${ui.eventChannel===v?'selected':''}>${v==='all'?'All sources':human(v)}</option>`).join('')}</select></label></div><div class="event-list">${list.length?list.map(ev=>`<article class="stream-entry"><span class="stream-marker ${tone(ev.severity)}">${eventMarker(ev)}</span><div class="grow"><div class="row wrap"><h3 style="margin:0"><button class="link" data-action="event" data-id="${e(ev.id)}">${e(ev.title)}</button></h3><span class="badge outline">${human(ev.channel)}</span>${ev.refreshStatus==='OLDER_EVIDENCE'||ev.refreshStatus==='IGNORED_DUPLICATE'?badge('UNKNOWN',human(ev.refreshStatus)):''}</div><p>${e(ev.message)}</p><div class="row" style="margin-top:7px"><button class="link tiny" data-action="service" data-id="${e(ev.serviceId)}">${e(serviceName(ev.serviceId))}</button><span class="tiny muted">· ${e(human(ev.refreshStatus))}</span></div></div><time datetime="${e(ev.occurredAt)}">${utcTime(ev.occurredAt)}</time></article>`).join(''):empty('No events from this source','Simulate an event or choose another source.')}</div></section>`;}
  function modelPage() {const diagram=modelDescriptions[ui.diagram];const rows=[['SystemEntity','AWS System / SystemSummary','Identity and business boundary'],['UserJourneyEntity','AWS UserJourney + local memberships','System-scoped journey and policy'],['ServiceEntity','AWS Service / ServiceSummary','Shared assessment unit'],['ResiliencePolicyEntity','AWS Policy + observed effective values','Four native components'],['AssessmentEntity','AWS AssessmentSummary','Execution and run evidence'],['FindingEntity','AWS Finding + local observations','Mutable service finding'],['RecommendationEntity','Local normalization + enrichment','Nested suggested changes; local estimates'],['DependencyDiscoveryConfig','AWS embedded value object','Enabled state and coverage evidence'],['DependencyEntity','AWS DependencySummary + local governance','DNS consumer reliance'],['TopologyEntity','Local paginated capture','Resources, nodes and typed edges']];return `<div class="model-tabs" role="tablist" aria-label="Entity relationship diagrams">${modelDescriptions.map(([title],i)=>`<button role="tab" aria-selected="${i===ui.diagram}" data-action="diagram" data-index="${i}" class="${i===ui.diagram?'active':''}">${i+1}. ${title}</button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${e(diagram[0])}</h2><div class="row"><a class="source-link" href="diagrams/${diagram[1]}.svg" target="_blank" rel="noopener">Open diagram ${icon('external')}</a><a class="source-link" href="diagrams/${diagram[1]}.md" download>Diagram note ${icon('download')}</a></div></div><div class="diagram" role="tabpanel" aria-label="${e(diagram[0])}"><img src="diagrams/${diagram[1]}.svg" alt="Entity relationship diagram: ${e(diagram[0])}. ${e(diagram[2])}"></div><div class="model-description">${e(diagram[2])}<div class="model-legend"><span><i class="legend-square"></i>AWS-backed record</span><span><i class="legend-square teal"></i>Local relationship, capture or projection</span></div></div></section><div class="review-grid"><section class="panel"><div class="panel-head"><h2>Review decisions</h2></div><div class="panel-body"><ul style="margin-top:0"><li>Explicit observation IDs and scoped relationship constraints.</li><li>List completeness separated from detail hydration.</li><li>Health, posture, execution and freshness kept independent.</li><li>Shared-service summaries retain their distinct contributors.</li><li>Estimates, governance and topology snapshots marked local.</li></ul><div class="row wrap"><a class="button small" href="review.md" target="_blank" rel="noopener">Review record ${icon('external')}</a><a class="button small" href="report.md" target="_blank" rel="noopener">Full report ${icon('external')}</a><a class="button small" href="api/index.md" target="_blank" rel="noopener">RPC API reference ${icon('external')}</a></div></div></section><section class="panel"><div class="panel-head"><h2>Prototype boundaries</h2></div><div class="panel-body"><p>All records describe a fictional commerce organization. Events, telemetry, costs and operator actions are synthetic. This app makes no AWS requests and uses no credentials. The separate mock RPC server has its own state; this browser workspace is not yet connected to it.</p><p>Native contract: <b>Resilience Hub v2</b>, model <b>2026-02-17</b>. Additional fields in the demo are labelled application-owned. The report provides the operation mapping and official references.</p><a class="source-link" href="https://docs.aws.amazon.com/resilience-hub/v2/APIReference/Welcome.html" target="_blank" rel="noopener">Official AWS API reference ${icon('external')}</a></div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>The ten requested concepts</h2></div><div class="table-wrap"><table class="data-tables"><thead><tr><th>Concept</th><th>Source & extension</th><th>Operator purpose</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${e(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
  function empty(title,message) {return `<div class="empty">${icon('search')}<h3>${e(title)}</h3><p>${e(message)}</p></div>`;}
  function render() {const active=document.activeElement,focusId=active?.id,selection=active?.selectionStart; $('app').innerHTML=layout();if(focusId==='search') {const el=$('search');el?.focus();if(selection!=null)el?.setSelectionRange?.(selection,selection);} }
  function openService(id,tab='overview') {if(!getService(id))return;ui.serviceId=id;ui.tab=tab;ui.nodeId=null;ui.edgeType='all';renderService();if(!$('service-dialog').open)$('service-dialog').showModal();}
  function renderService() {const s=getService(ui.serviceId);if(!s)return;const h=health(s),p=posture(s);const tabs=[['overview','Overview'],['findings',`Findings (${findingCollection(s).latestCapture||findingCollection(s).observedCount?`${openFindings(s).length} observed open`:'not collected'})`],['policy','Policy & posture'],['dependencies','Dependencies'],['topology','Topology'],['assessments','Assessments']];$('service-dialog').innerHTML=`<div class="dialog-head"><button class="icon-button close-button" data-action="close-service" aria-label="Close service details">${icon('close')}</button><div class="eyebrow">SERVICE · ${e(s.owner)}</div><h2>${e(s.name)}</h2><p>${e(s.description)}</p><div class="row wrap">${badge(h.state)}${badge(p.state,p.state==='UNKNOWN'?'Posture unknown':p.state==='ACHIEVABLE'?'Targets achievable':'Resilience at risk')}<span class="badge outline">${e(s.regions?.join(' · '))}</span>${s.associations?.length>1?`<span class="badge outline">Shared across ${s.associations.length} systems</span>`:''}<button class="button small" data-action="scenarios" style="margin-left:auto">${icon('play')}Simulate event</button></div></div><div class="detail-tabs" role="tablist" aria-label="Service details">${tabs.map(([id,name])=>`<button role="tab" aria-selected="${ui.tab===id}" data-action="service-tab" data-tab="${id}" class="${ui.tab===id?'active':''}">${name}</button>`).join('')}</div><div class="detail-body" role="tabpanel">${ui.tab==='overview'?serviceOverview(s):ui.tab==='findings'?serviceFindingList(s):ui.tab==='policy'?servicePolicy(s):ui.tab==='dependencies'?serviceDependencies(s):ui.tab==='topology'?serviceTopology(s):serviceAssessments(s)}</div>`;}
  function propertyList(rows) {return `<dl class="property-list">${rows.map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
  function serviceOverview(s) {const h=health(s),p=posture(s),dd=s.dependencyDiscovery||{};return `<div class="detail-stats"><div class="detail-stat"><span class="field-label">RUNTIME HEALTH</span>${badge(h.state)}<p>${e(h.source||'No monitoring source')} · ${ago(h.observedAt)}</p></div><div class="detail-stat"><span class="field-label">RESILIENCE POSTURE</span>${badge(p.state)}<p>Last evidence · ${ago(p.observedAt)}</p></div><div class="detail-stat"><span class="field-label">ASSESSMENT EXECUTION</span>${badge(s.assessmentStatus)}<p>Separate from last known posture</p></div><div class="detail-stat"><span class="field-label">DEPENDENCY DISCOVERY</span>${badge(dd.status)}<p>${dd.eligibleResourceCount==null?'Eligibility not yet known':`${dd.eligibleResourceCount} eligible resources`}</p></div></div>${h.state==='UNKNOWN'?`<div class="notice amber">${icon('clock')}<p>${h.stale?'The last health signal has expired.':'No usable runtime health signal is available.'} This service is shown as unknown until new telemetry arrives.</p></div>`:`<div class="notice ${h.state==='HEALTHY'?'neutral':'amber'}">${icon('pulse')}<p><b>${e(h.reason||'Runtime monitoring signal')}</b>${h.latencyMs!=null?` · p95 latency ${number(h.latencyMs)} ms`:''}${h.errorRate!=null?` · error rate ${e(h.errorRate)}%`:''}<br><span class="tiny">Measured ${utcTime(h.observedAt)} · expires ${utcTime(h.expiresAt)} · synthetic telemetry</span></p></div>`}${serviceEvidence(s)}<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Service identity</h2></div><div class="panel-body">${propertyList([['Owner',e(s.owner)],['Account',`<span class="mono">${e(s.accountId)}</span>`],['Regions',e(s.regions.join(', '))],['Service ARN',`<span class="mono">${e(s.arn)}</span>`],['Created',utcTime(s.createdAt,true)],['Permissions',e(s.permissionModel?.invokerRoleName||'Not loaded')]])}<p class="tiny muted" style="margin:12px 0 0">The permission model authorizes AWS discovery and assessment. It is separate from operator access to this UI.</p></div></section><section class="panel"><div class="panel-head"><h2>Systems & user journeys</h2></div><div class="panel-body">${(s.associations||[]).map(a=>`<div class="association"><h3>${e(state.systems.find(sys=>sys.id===a.systemId)?.name||a.systemId)}</h3><div class="chips">${a.journeyIds?.length?a.journeyIds.map(id=>`<span class="chip">${e(state.journeys.find(j=>j.id===id)?.name||id)}</span>`).join(''):'<span class="tiny muted">Associated directly with this system</span>'}</div></div>`).join('')||'<p class="tiny muted">No system associations loaded.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Input sources</h2></div><div class="panel-body">${(s.inputSources||[]).map(input=>`<div class="input-source">${icon('layers')}<div><b>${e(input.name||input.id)}</b><small>${e(input.type)} · ${e(input.description||input.sourceArn||input.arn||input.sourceIdentifier||'Imported resource scope')}</small></div></div>`).join('')||'<p class="tiny muted">No input sources loaded.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Resource discovery</h2></div><div class="panel-body">${badge(s.resourceDiscovery?.status)}${propertyList([['Last run',utcTime(s.resourceDiscovery?.lastRunAt,true)],['Coverage',e(s.resourceDiscovery?.errorMessage||s.resourceDiscovery?.error||s.resourceDiscovery?.message||(s.resourceDiscovery?.status==='SUCCEEDED'?'Inventory collection reported success for its configured scope.':'Inventory completeness has not been established.'))]])}<button class="link tiny" data-action="service-tab" data-tab="topology" style="margin-top:10px">Inspect captured topology →</button></div></section></div>`;}
  function serviceFindingList(s) {const collection=findingCollection(s),list=findings(s).sort((a,b)=>({HIGH:0,MEDIUM:1,LOW:2}[a.severity]-{HIGH:0,MEDIUM:1,LOW:2}[b.severity]));return `<div class="notice neutral">${icon('info')}<p>These are observed service findings. The API does not expose an assessment-to-finding foreign key. Resolving a finding records operator triage. Assessment completion and disposition readback do not verify a repair; independent evidence is required.</p></div>${collection.status!=='COMPLETE'?`<div class="notice amber">${icon('info')}<p><b>Finding coverage gap.</b> ${e(collection.reason)}</p></div>`:''}${list.length?list.map(f=>`<article class="finding-card"><div class="row wrap">${badge(f.severity)}${badge(f.status)}<span class="tiny muted">${e(human(f.policyComponent))}</span></div><h3><button class="link" data-action="finding" data-id="${e(f.id)}">${e(f.name)}</button></h3><p>${e(f.description)}</p><div class="row between"><span class="muted">${e(recommendationCount(f))} · ${ago(f.updatedAt)}</span><button class="link tiny" data-action="finding" data-id="${e(f.id)}">Review & triage →</button></div></article>`).join(''):empty('No findings loaded','An empty current finding list does not prove resilience without fresh assessment evidence.')}`;}
  const componentLabels={availabilitySlo:'Availability SLO',dataRecovery:'Data recovery',multiAz:'Multi-AZ recovery',multiRegion:'Multi-Region recovery'};
  const metricLabels={availabilitySlo:'Availability SLO',dataRecoveryTimeBetweenBackups:'Backup interval',multiAzDrApproach:'Multi-AZ strategy',multiAzRpo:'Multi-AZ RPO',multiAzRto:'Multi-AZ RTO',multiRegionDrApproach:'Multi-Region strategy',multiRegionRpo:'Multi-Region RPO',multiRegionRto:'Multi-Region RTO'};
  function servicePolicy(s) {const p=posture(s),direct=state.policies.find(x=>x.id===s.policyId);const inherited=[...new Set((s.associations||[]).flatMap(a=>a.journeyIds||[]).map(id=>state.journeys.find(j=>j.id===id)?.policyId).filter(Boolean))].map(id=>state.policies.find(p=>p.id===id)).filter(Boolean);return `<div class="notice ${p.state==='NOT_ACHIEVABLE'?'amber':'neutral'}">${icon('shield')}<p><b>${p.state==='UNKNOWN'?'No returned posture evidence.':`Last observed posture: ${human(p.state)}.`}</b> ${p.observedAt?`Observed ${utcTime(p.observedAt,true)}.`:''} A failed newer run does not replace these results. Shared journeys may have different objectives.</p></div><div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Component achievability</h2></div><div class="panel-body">${propertyList(Object.entries(componentLabels).map(([key,label])=>[label,badge(typeof p.components?.[key]==='object'?p.components[key]?.state:p.components?.[key]||'UNKNOWN')]))}<p class="tiny muted" style="margin:13px 0 0">Unknown is a UI state for missing evidence. The native achievability values are ACHIEVABLE and NOT_ACHIEVABLE.</p></div></section><section class="panel"><div class="panel-head"><h2>Applicable policies</h2></div><div class="panel-body"><div class="association"><h3>Direct assignment</h3><p>${e(direct?.name||'No direct service policy')}</p></div><div class="association"><h3>Inherited through journeys</h3><p>${inherited.map(p=>e(p.name)).join('<br>')||'No inherited policy in this capture'}</p></div><p class="tiny muted" style="margin:13px 0 0">The stricter applicable objective is reflected in effective targets. Account ownership and assignment path are different facts.</p></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Observed effective targets</h2><span class="badge outline">Captured context</span></div><div class="table-wrap"><table><thead><tr><th>Objective</th><th>Target</th><th>Source policy</th><th>Assignment</th><th>Ownership</th></tr></thead><tbody>${(s.effectiveTargets||[]).map(t=>`<tr><td>${e(metricLabels[t.metric]||human(t.metric))}</td><td class="metric-value">${e(typeof t.value==='string'&&t.value.includes('_')?human(t.value):t.value)}${t.unit?` ${e(t.unit)}`:''}</td><td>${e(t.policyName)}<span class="cell-sub">${e(t.policyId?'Policy reference resolved in mock context':'Unresolved policy reference')}</span></td><td>${e(human(t.assignment))}</td><td>${e(human(t.ownership))}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">${icon('info')}SELF / CROSS_ACCOUNT denotes ownership. Assignment and resolved policy references are local evidence.</div></section>`;}
  function serviceDependencies(s) {const dd=s.dependencyDiscovery||{};return `<section class="discovery-status"><div><div class="row"><h3>Dependency discovery</h3>${badge(dd.status)}</div><p>${dd.eligibleResourceCount==null?'Resource eligibility is not yet known.':`${dd.eligibleResourceCount} eligible resources.`} ${e(dd.message||'Discovery configuration observed.')}<br>Updated ${utcTime(dd.updatedAt,true)}</p></div><button class="button small" data-action="discovery" data-id="${s.id}" data-enable="${dd.status==='DISABLED'}">${dd.status==='DISABLED'?'Enable discovery':'Disable discovery'}</button></section>${dd.eligibleResourceCount===0?'<div class="notice amber">'+icon('info')+'<p>Discovery has zero eligible resources. This is a coverage gap, not evidence that the service has no dependencies.</p></div>':''}<section class="panel">${dependencyTable(state.dependencies.filter(d=>d.serviceId===s.id))}</section><p class="tiny muted" style="margin-top:15px">Criticality is attached to this consumer relationship. DNS observations do not establish runtime health or a native link to a topology node.</p>`;}
  function serviceTopology(s) {const top=[...state.topologies].filter(t=>t.serviceId===s.id).sort((a,b)=>new Date(b.captureEndedAt)-new Date(a.captureEndedAt))[0];if(!top)return empty('Topology has not been captured','Resource and edge collections will populate a local snapshot.');const nodes=top.nodes,edges=top.edges.filter(edge=>ui.edgeType==='all'||edge.type===ui.edgeType),width=Math.max(760,...nodes.map(n=>(n.x||0)+190)),height=Math.max(340,...nodes.map(n=>(n.y||0)+100));const selected=nodes.find(n=>n.id===ui.nodeId);const svgNodes=nodes.map((n,i)=>{const x=n.x??50+(i%3)*230,y=n.y??50+Math.floor(i/3)*120;return `<g class="topology-node ${n.status==='UNRESOLVED'?'unresolved':''} ${n.id===ui.nodeId?'selected':''}" data-action="node" data-id="${e(n.id)}" tabindex="0" role="button" aria-label="Inspect ${e(n.name)}" transform="translate(${x},${y})"><rect width="166" height="58" rx="8"/><text x="12" y="23" font-size="11" font-weight="600">${e(n.name.length>24?n.name.slice(0,22)+'…':n.name)}</text><text x="12" y="42" font-size="8" opacity=".65">${e(n.status==='UNRESOLVED'?'Unresolved resource':String(n.type||'Unknown').split('::').pop().replace(/([a-z])([A-Z])/g,'$1 $2'))}</text></g>`;}).join('');const svgEdges=edges.map(edge=>{const src=nodes.find(n=>n.id===edge.source),dst=nodes.find(n=>n.id===edge.target);if(!src||!dst)return '';let sx=(src.x||0)+83,sy=(src.y||0)+29,tx=(dst.x||0)+83,ty=(dst.y||0)+29;const horizontal=Math.abs(tx-sx)>Math.abs(ty-sy);if(horizontal){const direction=Math.sign(tx-sx);sx+=83*direction;tx-=85*direction;}else{const direction=Math.sign(ty-sy);sy+=29*direction;ty-=31*direction;}return `<path class="topology-edge ${edge.type.toLowerCase()}" marker-end="url(#edge-arrow)" d="M${sx},${sy} C${horizontal?sx+(tx-sx)*.55:sx},${horizontal?sy:sy+(ty-sy)*.55} ${horizontal?sx+(tx-sx)*.45:tx},${horizontal?ty:sy+(ty-sy)*.45} ${tx},${ty}"/>`;}).join('');return `<div class="row between wrap" style="margin-bottom:16px"><div class="topology-summary" style="margin:0">${badge(top.collectionStatus)}<span>${top.resourceCount} captured resources · ${top.edgeCount} edges · ${top.unresolvedCount} unresolved</span><span>Captured ${utcTime(top.captureEndedAt,true)}</span></div><select id="edge-type" class="filter-select" aria-label="Filter topology edge type">${['all','DATA_FLOW','CONTAINMENT','OBSERVABILITY','PERMISSIONS'].map(v=>`<option value="${v}" ${v===ui.edgeType?'selected':''}>${v==='all'?'All edge types':human(v)}</option>`).join('')}</select></div><div class="notice neutral">${icon('layers')}<p><b>${e(top.queryScope?.illustration||'Selected resource scope')}.</b> ${e(top.coverageMessage||'')}<br><span class="tiny">Broader mock inventory: ${e(top.totalServiceResourceCount??'unknown')} resources. Resource query billable=${e(top.queryScope?.billable??'default')}.</span></p></div><div class="topology-canvas"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Captured topology for ${e(s.name)}"><title>${e(s.name)} resource topology</title><defs><marker id="edge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#87ada0"/></marker></defs>${svgEdges}${svgNodes}</svg></div><div class="legend-row"><span><i class="legend-line"></i>Data flow / permissions</span><span><i class="legend-line dashed"></i>Containment</span><span><i class="legend-line dotted"></i>Observability</span><span>Click a resource to inspect</span></div>${selected?`<div class="node-detail"><b>${e(selected.name)}</b><p class="mono">${e(selected.resourceIdentifier)}</p><p>${e(selected.type)} · ${e(selected.region||'Region unknown')} · ${e(selected.accountId||'Account unknown')} · ${e(selected.status)}</p></div>`:''}<div class="notice neutral">${icon('info')}<p>This is a local capture of <span class="code-key">ListResources</span> and <span class="code-key">ListServiceTopologyEdges</span>. Complete means the selected collections finished, not an atomic AWS snapshot. Edge type alone does not establish failure propagation.</p></div>`;}
  function serviceAssessments(s) {const runs=state.assessments.filter(a=>a.serviceId===s.id).sort((a,b)=>new Date(b.startedAt||0)-new Date(a.startedAt||0));return `<div class="row between wrap" style="margin-bottom:17px"><div><h3>Assessment history</h3><p class="tiny muted" style="margin:0">Execution status is independent of the last returned posture.</p></div><button class="button primary" data-action="start-assessment" data-id="${s.id}" ${['IN_PROGRESS','PENDING'].includes(s.assessmentStatus)?'disabled':''}>${icon('play')}Start assessment</button></div>${['IN_PROGRESS','PENDING'].includes(s.assessmentStatus)?`<div class="notice">${icon('clock')}<p>An assessment is active. Use <b>Assessment completes</b> in the event simulator to deliver a synthetic completion. No progress percentage is claimed.</p></div>`:''}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Assessment</th><th>Status</th><th>Started</th><th>Findings</th><th>Run cost</th></tr></thead><tbody>${runs.map(a=>`<tr><td><span class="mono">${e(a.assessmentId||a.id)}</span>${a.error||a.errorCode?`<span class="cell-sub text-bad">${e(a.errorCode||a.error)}</span>`:''}</td><td>${badge(a.status)}${a.step?`<span class="cell-sub">${e(human(a.step))}</span>`:''}</td><td class="muted nowrap">${utcTime(a.startedAt,true)}${a.endedAt?`<span class="cell-sub">Ended ${utcTime(a.endedAt)}</span>`:''}</td><td>${a.totalFindings==null?'—':a.totalFindings}</td><td>${a.cost?.amount!=null?`$${Number(a.cost.amount).toFixed(2)}`:a.estimatedAssessmentCost?.amount!=null?`$${Number(a.estimatedAssessmentCost.amount).toFixed(2)}`:'—'}<span class="cell-sub">Assessment execution</span></td></tr>`).join('')}</tbody></table></div></section><div class="notice neutral" style="margin-top:17px">${icon('info')}<p>Run cost is distinct from a remediation estimate. Finding captures may be correlated with a run, but findings have no native assessment foreign key.</p></div>`;}
  function openInspector(kind,id) {ui.inspector={kind,id};renderInspector();if(!$('inspector-dialog').open)$('inspector-dialog').showModal();}
  function inspectorHeader(eyebrow,title,description='') {return `<div class="dialog-head"><button class="icon-button close-button" data-action="close-inspector" aria-label="Close record details">${icon('close')}</button><div class="eyebrow">${e(eyebrow)}</div><h2>${e(title)}</h2>${description?`<p>${e(description)}</p>`:''}</div>`;}
  function renderInspector() {const {kind,id}=ui.inspector||{};let html='';if(kind==='finding')html=findingInspector(state.findings.find(f=>f.id===id));if(kind==='dependency')html=dependencyInspector(state.dependencies.find(d=>d.id===id));if(kind==='event')html=eventInspector(state.events.find(ev=>ev.id===id));if(kind==='scenarios')html=scenarioInspector();if(kind==='reset')html=inspectorHeader('DEMO CONTROLS','Reset this workspace?','Restore the reviewed synthetic portfolio and clear this version’s locally saved changes.')+`<div class="inspector-body"><p>This resets simulated events, finding triage and dependency edits in the current workspace. Earlier saved versions remain untouched. Export a snapshot first to retain this current session.</p><div class="form-actions"><button class="button" data-action="close-inspector">Keep exploring</button><button class="button primary" data-action="reset">Reset demo</button></div></div>`;$('inspector-dialog').innerHTML=html;}
  function findingInspector(f) {if(!f)return '';return inspectorHeader(`${serviceName(f.serviceId)} · FAILURE MODE`,f.name)+`<div class="inspector-body"><div class="row wrap">${badge(f.severity)}${badge(f.status)}<span class="badge outline">${e(human(f.failureCategory))}</span></div><h3>What could fail</h3><p>${e(f.description)}</p><p>${e(f.reasoning||'')}</p>${f.status==='RESOLVED'&&f.verification==='UNVERIFIED'?'<div class="notice amber">'+icon('clock')+'<p>Marked resolved by an operator. Remediation is awaiting independent verification evidence; assessment completion alone does not establish repair.</p></div>':''}${f.status==='IRRELEVANT'?'<div class="notice neutral">'+icon('info')+'<p>This finding is suppressed as irrelevant. Suppression does not establish that the underlying failure mode was fixed.</p></div>':''}<h3>Recommended changes</h3>${!Array.isArray(f.recommendations)?(f.recommendations===null?'<p>Recommendation detail is explicitly unavailable (null). This is not a known empty result.</p>':'<p>Detailed recommendation arrays have not been returned. Missing is not the same as empty.</p>'):f.recommendations.length?f.recommendations.map(rec=>`<article class="recommendation"><span class="badge outline">${e(human(rec.category))}</span><h4>${e(rec.title||'Suggested changes')}</h4><ul>${(rec.suggestedChanges||[]).map(change=>`<li>${e(change)}</li>`).join('')}</ul>${rec.estimate?`<div class="estimate"><span><b>Local estimate:</b> ${e(rec.estimate.amount==null?'Not estimated':rec.estimate.basis==='engineering hours'?`${rec.estimate.amount} hours`:`${rec.estimate.currency} ${number(rec.estimate.amount)}`)} · ${e(rec.estimate.basis)}</span><span>${e(rec.estimate.complexity==='UNESTIMATED'?'Complexity not estimated':human(rec.estimate.complexity)+' complexity')}</span><span>${e(rec.estimate.source)}</span></div>`:''}</article>`).join(''):'<p>The captured detail contains no recommendation groups.</p>'}<p class="tiny muted">Recommendation titles, estimates and complexity are Northstar enrichment. Native recommendation groups contain suggested changes.</p><hr class="section-divider"><h3>Operator triage</h3><form id="finding-form" data-id="${e(f.id)}"><div class="form-field"><label for="triage-status">Disposition</label><select id="triage-status" name="status">${['OPEN','RESOLVED','IRRELEVANT'].map(status=>`<option value="${status}" ${status===f.status?'selected':''}>${human(status)}</option>`).join('')}</select></div><div class="form-field"><label for="triage-comment">Operator comment</label><textarea id="triage-comment" name="comment" maxlength="2000" placeholder="Record the reason for this triage decision…">${e(f.comment||'')}</textarea></div><div class="row between wrap"><span class="tiny muted">Mock UpdateFailureModeFinding</span><button class="button primary" type="submit">Save disposition</button></div></form><details style="margin-top:22px"><summary class="tiny muted">Observation provenance</summary>${propertyList([['Finding ID',`<span class="mono">${e(f.findingId)}</span>`],['Observation ID',`<span class="mono">${e(f.observationId)}</span>`],['Representation',e(f.representation)],['Detail observed',utcTime(f.detailObservedAt,true)],['Policy component',e(human(f.policyComponent))]])}</details></div>`;}
  function dependencyInspector(d) {if(!d)return '';const samples=d.queryRange?.dataPoints,count=Array.isArray(samples)&&samples.length>0&&samples.every(p=>Number.isFinite(p.queryCount)&&p.queryCount>=0)?samples.reduce((n,p)=>n+p.queryCount,0):null;return inspectorHeader(`${serviceName(d.serviceId)} · DNS DEPENDENCY`,d.name,d.dnsName)+`<div class="inspector-body"><div class="row">${badge(d.governance?.allowedStatus||'UNKNOWN')}<span class="badge outline">Local governance</span></div>${propertyList([['Consumer',e(serviceName(d.serviceId))],['Location',e(human(d.location))],['Provider',e(d.provider||'Unknown')],['Source regions',e(d.sourceRegions?.join(', '))],['Last detected',utcTime(d.lastDetectedTime,true)],['DNS queries',count==null?(Array.isArray(samples)&&samples.length===0?'No query samples returned':'Query counts unavailable'):`${number(count)} across ${samples.length} returned samples`],['Query window',d.queryRange?.startTime&&d.queryRange?.endTime?`${utcTime(d.queryRange.startTime,true)} – ${utcTime(d.queryRange.endTime,true)}`:'Not captured'],['Governance source',e(d.governance?.source||'Not evaluated')]])}${d.resolution?`<div class="notice neutral" style="margin-top:15px">${icon('network')}<p><b>Locally resolved service:</b> ${e(serviceName(d.resolution.serviceId))}. ${e(d.resolution.evidence)}<br>This is an evidenced application link, not a native topology foreign key.</p></div>`:''}<h3>Consumer criticality</h3><p>Criticality describes this service’s reliance on the dependency. It does not report the dependency’s health.</p><form id="dependency-form" data-id="${e(d.id)}"><div class="form-field"><label for="dependency-criticality">Criticality</label><select id="dependency-criticality" name="criticality">${['HARD','SOFT','UNKNOWN'].map(v=>`<option value="${v}" ${v===d.criticality?'selected':''}>${human(v)}</option>`).join('')}</select></div><div class="form-field"><label for="dependency-comment">Operator comment</label><textarea id="dependency-comment" name="comment" maxlength="2000">${e(d.comment||'')}</textarea></div><div class="row between"><span class="tiny muted">Mock UpdateDependency</span><button class="button primary" type="submit">Save criticality</button></div></form></div>`;}
  function eventInspector(ev) {if(!ev)return '';return inspectorHeader(`${human(ev.channel)} · ${serviceName(ev.serviceId)}`,ev.title,ev.message)+`<div class="inspector-body">${propertyList([['Occurred',utcTime(ev.occurredAt,true)],['Received',utcTime(ev.receivedAt,true)],['Refresh outcome',e(human(ev.refreshStatus))],['Entity linkage',e(human(ev.linkage))],['Stream owner',`<span class="mono">${e(ev.streamOwner)}</span>`],['Source event ID',`<span class="mono">${e(ev.sourceEventId)}</span>`]])}<div class="notice neutral" style="margin-top:17px">${icon('refresh')}<p>The event and its receipt are retained separately from the selected current observation. An older event cannot directly roll back current service evidence.</p></div><details><summary class="tiny muted">Normalized mock event</summary><pre class="record-json">${e(JSON.stringify(ev,null,2))}</pre></details></div>`;}
  function scenarioInspector() {const choices=M.scenarios||[];return inspectorHeader('DEMO CONTROLS','Make the model move','Simulate an operational event and inspect what changes across the workspace.')+`<div class="inspector-body"><div class="scenario-grid">${choices.map(s=>`<button class="scenario-option" data-action="scenario" data-id="${e(s.id)}">${icon(s.id.includes('latency')?'pulse':s.id.includes('dependency')?'network':s.id.includes('expired')?'clock':s.id.includes('failed')?'alert':s.id.includes('duplicate')?'layers':'check')}<span><h3>${e(s.label||s.name||human(s.id))}</h3><p>${e(s.id==='assessment-completed'&&ui.serviceId?`Deliver a successful assessment for ${serviceName(ui.serviceId)} and refresh its captured evidence.`:s.id==='assessment-failed'&&ui.serviceId?`Fail a new assessment for ${serviceName(ui.serviceId)} while retaining its last successful posture.`:s.description)}</p></span>${icon('arrow','arrow')}</button>`).join('')}</div><p class="clock-note">The demo clock is ${utcTime(state.now,true)}. Each scenario advances it deterministically. No live AWS calls or background polling occur.</p></div>`;}
  function exportSnapshot() {const payload={exportedAt:new Date().toISOString(),kind:'SYNTHETIC_DEMO_SNAPSHOT',schemaVersion:state.schemaVersion,notes:'All source records and telemetry are synthetic. Local enrichments are not native AWS API fields. This export contains only the reviewed current workspace; earlier browser sessions are not included.',state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='northstar-resilience-snapshot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Synthetic workspace snapshot exported.');}
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;switch(action){case'navigate':event.preventDefault();navigate(el.dataset.view);break;case'menu':ui.menu=!ui.menu;render();break;case'service':openService(id,el.dataset.tab||'overview');break;case'close-service':$('service-dialog').close();ui.serviceId=null;break;case'service-tab':ui.tab=el.dataset.tab;renderService();$('service-dialog').querySelector('[role=tab][aria-selected=true]')?.focus({preventScroll:true});break;case'finding':openInspector('finding',id);break;case'dependency':openInspector('dependency',id);break;case'event':openInspector('event',id);break;case'close-inspector':$('inspector-dialog').close();ui.inspector=null;break;case'scenarios':openInspector('scenarios');break;case'scenario':{const result=M.applyScenario(state,id,ui.serviceId||undefined);$('inspector-dialog').close();ui.inspector=null;mutate(result);break;}case'export':exportSnapshot();break;case'dismiss-cache-notice':legacyCacheNotice=false;render();break;case'reset-confirm':openInspector('reset');break;case'reset':state=fresh();save();$('inspector-dialog').close();$('service-dialog').close();ui.serviceId=null;ui.inspector=null;ui.systemId='all';ui.journeyId='all';ui.query='';render();toast('Reviewed mock portfolio restored.');break;case'diagram':ui.diagram=Number(el.dataset.index);render();document.querySelector('.model-tabs [aria-selected=true]')?.focus({preventScroll:true});break;case'scope-system':ui.systemId=id;ui.journeyId='all';navigate('services');break;case'scope-journey':ui.journeyId=id;ui.systemId=state.journeys.find(j=>j.id===id)?.systemId||'all';navigate('services');break;case'discovery':mutate(M.setDiscovery(state,id,el.dataset.enable==='true'));break;case'start-assessment':mutate(M.startAssessment(state,id));break;case'node':ui.nodeId=id;renderService();$('service-dialog').querySelector('.topology-node.selected')?.focus({preventScroll:true});break;}});
  document.addEventListener('keydown',event=>{if(event.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...event.target.closest('[role=tablist]').querySelectorAll('[role=tab]')],index=tabs.indexOf(event.target);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();return;}if((event.key==='Enter'||event.key===' ')&&event.target.matches('.topology-node')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  document.addEventListener('change',event=>{const {id,value}=event.target;const map={'system-filter':'systemId','journey-filter':'journeyId','finding-status':'findingStatus','severity-filter':'severity','criticality-filter':'criticality','event-channel':'eventChannel','edge-type':'edgeType'};if(!map[id])return;ui[map[id]]=value;if(id==='system-filter')ui.journeyId='all';if(id==='edge-type')renderService();else render();});
  document.addEventListener('input',event=>{if(event.target.id==='search'){ui.query=event.target.value;render();}});
  document.addEventListener('submit',event=>{if(event.target.id==='finding-form'){event.preventDefault();const form=new FormData(event.target);const result=M.updateFinding(state,event.target.dataset.id,form.get('status'),form.get('comment'));mutate(result);renderInspector();}if(event.target.id==='dependency-form'){event.preventDefault();const form=new FormData(event.target);const result=M.updateDependency(state,event.target.dataset.id,form.get('criticality'),form.get('comment'));mutate(result);renderInspector();}});
  $('service-dialog').addEventListener('cancel',()=>{ui.serviceId=null;});
  $('inspector-dialog').addEventListener('cancel',()=>{ui.inspector=null;});
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(views.includes(view)){ui.view=view;render();}});
  render();
})();
